const cmp=(id,title,kind,cases)=>({id,title,kind,type:'compare',cases});
export const cycleData={time:[0,1,2,3,4],prey:[8,16,12,6,8],predator:[2,3,6,4,2]};
export const fieldCounts=[2,0,4,8,1,3,7,6,0,2,5,9,1,4,6,10];
export const sampleSchedule=[[0,0],[3,1],[1,2],[2,3]];
export const transectData=[{distance:0,light:20,counts:[2,3,1]},{distance:2,light:40,counts:[4,5,3]},{distance:4,light:60,counts:[6,7,5]},{distance:6,light:80,counts:[8,9,7]}];
export const mean=a=>a.reduce((n,v)=>n+v,0)/a.length;
export function estimatePopulation(counts,quadratArea,habitatArea){if(!Array.isArray(counts)||!counts.length||counts.some(v=>!Number.isFinite(v)||v<0)||!Number.isFinite(quadratArea)||!Number.isFinite(habitatArea)||quadratArea<=0||habitatArea<=0)throw new RangeError('Use non-negative counts, positive areas and at least one sample.');return mean(counts)/quadratArea*habitatArea;}
export function fieldCount(x,y){if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||x>3||y<0||y>3)throw new RangeError('Choose a field coordinate0–3.');return fieldCounts[y*4+x];}
export function graphValid(v){return v.xAxis==='time'&&v.yAxis==='population'&&Number(v.scale)===20&&cycleData.prey.every((n,i)=>numericEco2(v.prey?.[i],n))&&cycleData.predator.every((n,i)=>numericEco2(v.predator?.[i],n));}
export function sampleValid(v){return Array.isArray(v.samples)&&v.samples.length===4&&sampleSchedule.every(([x,y],i)=>v.samples[i]?.x===x&&v.samples[i]?.y===y&&v.samples[i]?.count===fieldCount(x,y))&&numericEco2(v.estimate,64)&&v.reason==='density';}
export function transectValid(v){return Array.isArray(v.stations)&&transectData.every((s,i)=>v.stations.includes(i))&&v.interpretation==='association';}
