export const tasksForEco2=k=>eco2Tasks[k];export const validEco2=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const advanceEco2=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;export const numericEco2=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;
